(async()=>{if(new URLSearchParams(location.search).get('profile')!=='upgrade-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,D=SurvivalData,U=SurvivalUpgrade;document.getElementById('welcome').hidden=true;q.setPlaying(false);const panel=document.createElement('section');panel.id='qa-panel';panel.style='position:fixed;inset:0;z-index:10000;background:#fff;color:#234;overflow:auto;padding:16px';document.body.append(panel);const report=document.createElement('pre');report.id='report';panel.append(report);const rows={};function check(name,ok){rows[name]=!!ok;report.textContent=JSON.stringify(rows,null,2);if(!ok)throw Error(name);}async function view(id,pose,hand='hammer'){q.close(false);q.apply({...D.fresh(),...pose,inventory:{hammer:1,pickaxe:1,compass:1,sword:1,flashlight:1,bow:1},hand,worldTime:pose.worldTime??360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);q.inventory();await wait(1300);q.close(false);q.sky.update(q.state,0,true);q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=id;im.src=q.renderer.domElement.toDataURL();im.style='width:49%';panel.append(im);q.setPlaying(false);}
q.apply(D.fresh());q.inventory();check('onlyKnownRecipes',document.querySelectorAll('[data-recipe-choice]').length===6&&!document.querySelector('[data-recipe-choice="sword"]'));check('shortIngredientsRed',getComputedStyle(document.querySelector('.ingredient.short')).backgroundColor==='rgb(244, 198, 194)');q.close(false);const chest=q.world.villageTreasures[0];q.apply({...D.fresh(),x:chest.x,y:chest.y,z:chest.z+1.5});check('villageTreasureTarget',q.nearestTarget()?.type==='villageTreasure');q.interact();check('blueprintLearned',D.knows(q.state,'sword'));q.inventory();check('learnedRecipeAppears',!!document.querySelector('[data-recipe-choice="sword"]'));check('treasureOneTime',U.treasure(q.state,chest)===null);q.close(false);check('newSaveValid',D.validSave(q.snapshot()));
const house=q.world.villageHouses[0];await view('house-outside',{x:house.x+8,z:house.z+12,y:W.ground(house.x+8,house.z+12),yaw:.55,pitch:.06});await view('house-inside',{x:house.x,z:house.z+1.5,y:house.y+.3,yaw:0,pitch:-.08});const npc=W.merchants[0];await view('villager',{x:npc.x,z:npc.z+2.5,y:npc.y,yaw:0,pitch:-.06},'compass');
const l=W.landmarks.find(l=>l.kind==='temple');await view('stairs',{x:l.x,z:l.z+16,y:q.world.floor(l.x,l.z+16,l.y,q.state),yaw:0,pitch:0},'pickaxe');
const d=SurvivalDungeons.dungeons[0];await view('dungeon-pit',{x:d.x,z:d.z+9,y:d.y,yaw:Math.PI,pitch:-.4});
const c=W.caves[0],p=c.paths.at(-2)[2],cp=W.cavePoint(c,p[0],p[1]);await view('deep-cave',{...cp,y:W.caveFloor(c,p[0],p[1]),yaw:Math.atan2(-c.fx,-c.fz),pitch:0},'flashlight');
await view('water-shore',{x:-389,z:-371,y:W.ground(-389,-371),yaw:-1.78,pitch:-.13},'compass');
const i=W.islands[8];await view('sky-island',{x:i.x,z:i.z+i.r*.7,y:i.y,yaw:0,pitch:.05},'compass');
await view('held-day',{x:0,z:24,y:W.ground(0,24),yaw:0,pitch:0},'bow');await view('held-night',{x:0,z:24,y:W.ground(0,24),yaw:0,pitch:0,worldTime:23/24*720},'bow');
q.apply(D.fresh());q.close(false);q.sky.update(q.state,0,true);await wait(700);const dry={...q.state,time:1000,x:0,z:24};check('drySoundZero',U.waterSound(dry)===0);const preview=document.createElement('button');preview.textContent='村の仕上がりを見る';preview.onclick=()=>{panel.hidden=true;q.close(false);q.apply({...D.fresh(),x:house.x+8,z:house.z+12,y:W.ground(house.x+8,house.z+12),yaw:.55,pitch:.06,inventory:{hammer:1},hand:'hammer',automaticTime:false,worldTime:360});q.setPlaying(true);};panel.prepend(preview);rows.done=true;report.textContent=JSON.stringify(rows,null,2);document.title='探索改善の確認完了';})().catch(e=>{document.title='QA error';const p=document.getElementById('report')||document.body.appendChild(document.createElement('pre'));p.id='report';p.textContent+='\n'+e.stack;});
